/// <summary>
/// Extension of <c>AgreementLineHistory</c> table
/// </summary>
[ExtensionOf(tableStr(AgreementLineHistory))]
final public class AVAAgreementLineHistoryDbt_Extension
{
}

Method.Source:
/// <summary>
///    Initializes an <c>AgreementLineHistory</c> record from an <c>AgreementLine</c> record.
/// </summary>
/// <param name="_line">
///    The <c>AgreementLine</c> record.
/// </param>
public void initFromAgreementLine(AgreementLine _line)
{
    next initFromAgreementLine(_line);

    this.AVAMainPosition        = _line.AVAMainPosition;
    this.AVAOrderConfirmation   = _line.AVAOrderConfirmation;
    this.AVAStopped             = _line.AVAStopped;
    this.AVAWidthCoilMM         = _line.AVAWidthCoilMM;
}

public void insert()
{
    next insert();

    AgreementLineHistory::avaCopyMarkup(this.avaGetAgreementLine(), this);
}

/// <summary>
/// Copies <c>Markup</c> table records linked to one record to another
/// </summary>
/// <param name = "_fromLine">Common - normally AgreementLine record</param>
/// <param name = "_toLine">Common - normally AgreementLineHistory record</param>
public static void avaCopyMarkup(Common _fromLine, Common _toLine)
{
    Markup::copy(NoYes::No, _fromLine, _toLine);
}

/// <summary>
/// gets related AgreementLine record
/// </summary>
/// <returns>AgreementLine</returns>
public AgreementLine avaGetAgreementLine()
{
    return AgreementLine::find(this.AgreementLine);
}

/// <summary>
/// Finds AgreementLineHistory record
/// </summary>
/// <param name = "_recId">RecId</param>
/// <param name = "_selectForUpdate">boolean</param>
/// <returns>AgreementLineHistory</returns>
public static AgreementLineHistory avaFindRecId(RecId _recId, boolean _selectForUpdate = false)
{
    AgreementLineHistory avaLineHistory;

    if(_selectForUpdate)
    {
        avaLineHistory.selectForUpdate(_selectForUpdate);
    }

    select firstonly avaLineHistory
        where avaLineHistory.RecId == _recId;

    return avaLineHistory;
}
